extension ServiceConfig: Equatable, Hashable {
    public static func ==(lhs: ServiceConfig, rhs: ServiceConfig) -> Bool {
        if lhs.defaultPageSize != rhs.defaultPageSize {
            return false
        }
        if lhs.enabledFeatures != rhs.enabledFeatures {
            return false
        }
        if lhs.maxMoveValueDepth != rhs.maxMoveValueDepth {
            return false
        }
        if lhs.maxOutputNodes != rhs.maxOutputNodes {
            return false
        }
        if lhs.maxPageSize != rhs.maxPageSize {
            return false
        }
        if lhs.maxQueryDepth != rhs.maxQueryDepth {
            return false
        }
        if lhs.maxQueryNodes != rhs.maxQueryNodes {
            return false
        }
        if lhs.maxQueryPayloadSize != rhs.maxQueryPayloadSize {
            return false
        }
        if lhs.maxTypeArgumentDepth != rhs.maxTypeArgumentDepth {
            return false
        }
        if lhs.maxTypeArgumentWidth != rhs.maxTypeArgumentWidth {
            return false
        }
        if lhs.maxTypeNodes != rhs.maxTypeNodes {
            return false
        }
        if lhs.mutationTimeoutMs != rhs.mutationTimeoutMs {
            return false
        }
        if lhs.requestTimeoutMs != rhs.requestTimeoutMs {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(defaultPageSize)
        hasher.combine(enabledFeatures)
        hasher.combine(maxMoveValueDepth)
        hasher.combine(maxOutputNodes)
        hasher.combine(maxPageSize)
        hasher.combine(maxQueryDepth)
        hasher.combine(maxQueryNodes)
        hasher.combine(maxQueryPayloadSize)
        hasher.combine(maxTypeArgumentDepth)
        hasher.combine(maxTypeArgumentWidth)
        hasher.combine(maxTypeNodes)
        hasher.combine(mutationTimeoutMs)
        hasher.combine(requestTimeoutMs)
    }
}



