/**
 * An error with an argument to a command
 *
 * # BCS
 *
 * The BCS serialized form for this type is defined by the following ABNF:
 *
 * ```text
 * command-argument-error =  type-mismatch
 * =/ invalid-bcs-bytes
 * =/ invalid-usage-of-pure-argument
 * =/ invalid-argument-to-private-entry-function
 * =/ index-out-of-bounds
 * =/ secondary-index-out-of-bound
 * =/ invalid-result-arity
 * =/ invalid-gas-coin-usage
 * =/ invalid-value-usage
 * =/ invalid-object-by-value
 * =/ invalid-object-by-mut-ref
 * =/ shared-object-operation-not-allowed
 *
 * type-mismatch                               = %d00
 * invalid-bcs-bytes                           = %d01
 * invalid-usage-of-pure-argument              = %d02
 * invalid-argument-to-private-entry-function  = %d03
 * index-out-of-bounds                         = %d04 u16
 * secondary-index-out-of-bound                = %d05 u16 u16
 * invalid-result-arity                        = %d06 u16
 * invalid-gas-coin-usage                      = %d07
 * invalid-value-usage                         = %d08
 * invalid-object-by-value                     = %d09
 * invalid-object-by-mut-ref                   = %d10
 * shared-object-operation-not-allowed         = %d11
 * ```
 */

public enum CommandArgumentError {
    
    /**
     * The type of the value does not match the expected type
     */
    case typeMismatch
    /**
     * The argument cannot be deserialized into a value of the specified type
     */
    case invalidBcsBytes
    /**
     * The argument cannot be instantiated from raw bytes
     */
    case invalidUsageOfPureArgument
    /**
     * Invalid argument to private entry function.
     * Private entry functions cannot take arguments from other Move functions.
     */
    case invalidArgumentToPrivateEntryFunction
    /**
     * Out of bounds access to input or results
     */
    case indexOutOfBounds(index: UInt16
    )
    /**
     * Out of bounds access to subresult
     */
    case secondaryIndexOutOfBounds(result: UInt16, subresult: UInt16
    )
    /**
     * Invalid usage of result.
     * Expected a single result but found either no return value or multiple.
     */
    case invalidResultArity(result: UInt16
    )
    /**
     * Invalid usage of Gas coin.
     * The Gas coin can only be used by-value with a TransferObjects command.
     */
    case invalidGasCoinUsage
    /**
     * Invalid usage of move value.
     */
    case invalidValueUsage
    /**
     * Immutable objects cannot be passed by-value.
     */
    case invalidObjectByValue
    /**
     * Immutable objects cannot be passed by mutable reference, &mut.
     */
    case invalidObjectByMutRef
    /**
     * Shared object operations such a wrapping, freezing, or converting to
     * owned are not allowed.
     */
    case sharedObjectOperationNotAllowed
    /**
     * Invalid argument arity. Expected a single argument but found a result
     * that expanded to multiple arguments.
     */
    case invalidArgumentArity
}


#if compiler(>=6)
extension CommandArgumentError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCommandArgumentError: FfiConverterRustBuffer {
    typealias SwiftType = CommandArgumentError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CommandArgumentError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .typeMismatch
        
        case 2: return .invalidBcsBytes
        
        case 3: return .invalidUsageOfPureArgument
        
        case 4: return .invalidArgumentToPrivateEntryFunction
        
        case 5: return .indexOutOfBounds(index: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 6: return .secondaryIndexOutOfBounds(result: try FfiConverterUInt16.read(from: &buf), subresult: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 7: return .invalidResultArity(result: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 8: return .invalidGasCoinUsage
        
        case 9: return .invalidValueUsage
        
        case 10: return .invalidObjectByValue
        
        case 11: return .invalidObjectByMutRef
        
        case 12: return .sharedObjectOperationNotAllowed
        
        case 13: return .invalidArgumentArity
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CommandArgumentError, into buf: inout [UInt8]) {
        switch value {
        
        
        case .typeMismatch:
            writeInt(&buf, Int32(1))
        
        
        case .invalidBcsBytes:
            writeInt(&buf, Int32(2))
        
        
        case .invalidUsageOfPureArgument:
            writeInt(&buf, Int32(3))
        
        
        case .invalidArgumentToPrivateEntryFunction:
            writeInt(&buf, Int32(4))
        
        
        case let .indexOutOfBounds(index):
            writeInt(&buf, Int32(5))
            FfiConverterUInt16.write(index, into: &buf)
            
        
        case let .secondaryIndexOutOfBounds(result,subresult):
            writeInt(&buf, Int32(6))
            FfiConverterUInt16.write(result, into: &buf)
            FfiConverterUInt16.write(subresult, into: &buf)
            
        
        case let .invalidResultArity(result):
            writeInt(&buf, Int32(7))
            FfiConverterUInt16.write(result, into: &buf)
            
        
        case .invalidGasCoinUsage:
            writeInt(&buf, Int32(8))
        
        
        case .invalidValueUsage:
            writeInt(&buf, Int32(9))
        
        
        case .invalidObjectByValue:
            writeInt(&buf, Int32(10))
        
        
        case .invalidObjectByMutRef:
            writeInt(&buf, Int32(11))
        
        
        case .sharedObjectOperationNotAllowed:
            writeInt(&buf, Int32(12))
        
        
        case .invalidArgumentArity:
            writeInt(&buf, Int32(13))
        
        }
    }
}


