    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Direction {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .forward
        
        case 2: return .backward
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: Direction, into buf: inout [UInt8]) {
        switch value {
        
        
        case .forward:
            writeInt(&buf, Int32(1))
        
        
        case .backward:
            writeInt(&buf, Int32(2))
        
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDirection_lift(_ buf: RustBuffer) throws -> Direction {
    return try FfiConverterTypeDirection.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeDirection_lower(_ value: Direction) -> RustBuffer {
    return FfiConverterTypeDirection.lower(value)
}


extension Direction: Equatable, Hashable {}






// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * An error that can occur during the execution of a transaction
 *
 * # BCS
 *
 * The BCS serialized form for this type is defined by the following ABNF:
 *
 * ```text
 *
 * execution-error =  insufficient-gas
 * =/ invalid-gas-object
 * =/ invariant-violation
 * =/ feature-not-yet-supported
 * =/ object-too-big
 * =/ package-too-big
 * =/ circular-object-ownership
 * =/ insufficient-coin-balance
 * =/ coin-balance-overflow
 * =/ publish-error-non-zero-address
 * =/ iota-move-verification-error
 * =/ move-primitive-runtime-error
 * =/ move-abort
 * =/ vm-verification-or-deserialization-error
 * =/ vm-invariant-violation
 * =/ function-not-found
 * =/ arity-mismatch
 * =/ type-arity-mismatch
 * =/ non-entry-function-invoked
 * =/ command-argument-error
 * =/ type-argument-error
 * =/ unused-value-without-drop
 * =/ invalid-public-function-return-type
 * =/ invalid-transfer-object
 * =/ effects-too-large
 * =/ publish-upgrade-missing-dependency
 * =/ publish-upgrade-dependency-downgrade
 * =/ package-upgrade-error
 * =/ written-objects-too-large
 * =/ certificate-denied
 * =/ iota-move-verification-timeout
 * =/ shared-object-operation-not-allowed
 * =/ input-object-deleted
 * =/ execution-cancelled-due-to-shared-object-congestion
 * =/ address-denied-for-coin
 * =/ coin-type-global-pause
 * =/ execution-cancelled-due-to-randomness-unavailable
 * =/ execution-cancelled-due-to-shared-object-congestion-v2
 * =/ invalid-linkage
 *
 * insufficient-gas                                       = %d00
 * invalid-gas-object                                     = %d01
 * invariant-violation                                    = %d02
 * feature-not-yet-supported                              = %d03
 * object-too-big                                         = %d04 u64 u64
 * package-too-big                                        = %d05 u64 u64
 * circular-object-ownership                              = %d06 object-id
 * insufficient-coin-balance                              = %d07
 * coin-balance-overflow                                  = %d08
 * publish-error-non-zero-address                         = %d09
 * iota-move-verification-error                           = %d10
 * move-primitive-runtime-error                           = %d11 (option move-location)
 * move-abort                                             = %d12 move-location u64
 * vm-verification-or-deserialization-error               = %d13
 * vm-invariant-violation                                 = %d14
 * function-not-found                                     = %d15
 * arity-mismatch                                         = %d16
 * type-arity-mismatch                                    = %d17
 * non-entry-function-invoked                             = %d18
 * command-argument-error                                 = %d19 u16 command-argument-error
 * type-argument-error                                    = %d20 u16 type-argument-error
 * unused-value-without-drop                              = %d21 u16 u16
 * invalid-public-function-return-type                    = %d22 u16
 * invalid-transfer-object                                = %d23
 * effects-too-large                                      = %d24 u64 u64
 * publish-upgrade-missing-dependency                     = %d25
 * publish-upgrade-dependency-downgrade                   = %d26
 * package-upgrade-error                                  = %d27 package-upgrade-error
 * written-objects-too-large                              = %d28 u64 u64
 * certificate-denied                                     = %d29
 * iota-move-verification-timeout                         = %d30
 * shared-object-operation-not-allowed                    = %d31
 * input-object-deleted                                   = %d32
 * execution-cancelled-due-to-shared-object-congestion    = %d33 (vector object-id)
 * address-denied-for-coin                                = %d34 address string
 * coin-type-global-pause                                 = %d35 string
 * execution-cancelled-due-to-randomness-unavailable      = %d36
 * execution-cancelled-due-to-shared-object-congestion-v2 = %d37 (vector object-id) u64
 * invalid-linkage                                        = %d38
 * ```
 */

public enum ExecutionError {
    
    /**
     * Insufficient Gas
     */
    case insufficientGas
    /**
     * Invalid Gas Object.
     */
    case invalidGasObject
    /**
     * Invariant Violation
     */
    case invariantViolation
    /**
     * Attempted to used feature that is not supported yet
     */
    case featureNotYetSupported
    /**
     * Move object is larger than the maximum allowed size
     */
    case objectTooBig(objectSize: UInt64, maxObjectSize: UInt64
    )
    /**
     * Package is larger than the maximum allowed size
     */
    case packageTooBig(objectSize: UInt64, maxObjectSize: UInt64
    )
    /**
     * Circular Object Ownership
     */
    case circularObjectOwnership(object: ObjectId
    )
    /**
     * Insufficient coin balance for requested operation
     */
    case insufficientCoinBalance
    /**
     * Coin balance overflowed an u64
     */
    case coinBalanceOverflow
    /**
     * Publish Error, Non-zero Address.
     * The modules in the package must have their self-addresses set to zero.
     */
    case publishErrorNonZeroAddress
    /**
     * IOTA Move Bytecode Verification Error.
     */
    case iotaMoveVerification
    /**
     * Error from a non-abort instruction.
     * Possible causes:
     * Arithmetic error, stack overflow, max value depth, etc."
     */
    case movePrimitiveRuntime(location: MoveLocation?
    )
    /**
     * Move runtime abort
     */
    case moveAbort(location: MoveLocation, code: UInt64
    )
    /**
     * Bytecode verification error.
     */
    case vmVerificationOrDeserialization
    /**
     * MoveVm invariant violation
     */
    case vmInvariantViolation
    /**
     * Function not found
     */
    case functionNotFound
    /**
     * Arity mismatch for Move function.
     * The number of arguments does not match the number of parameters
     */
    case arityMismatch
    /**
     * Type arity mismatch for Move function.
     * Mismatch between the number of actual versus expected type arguments.
     */
    case typeArityMismatch
    /**
     * Non Entry Function Invoked. Move Call must start with an entry function.
     */
    case nonEntryFunctionInvoked
    /**
     * Invalid command argument
     */
    case commandArgument(argument: UInt16, kind: CommandArgumentError
    )
    /**
     * Type argument error
     */
    case typeArgument(
        /**
         * Index of the problematic type argument
         */typeArgument: UInt16, kind: TypeArgumentError
    )
    /**
     * Unused result without the drop ability.
     */
    case unusedValueWithoutDrop(result: UInt16, subresult: UInt16
    )
    /**
     * Invalid public Move function signature.
     * Unsupported return type for return value
     */
    case invalidPublicFunctionReturnType(index: UInt16
    )
    /**
     * Invalid Transfer Object, object does not have public transfer.
     */
    case invalidTransferObject
    /**
     * Effects from the transaction are too large
     */
    case effectsTooLarge(currentSize: UInt64, maxSize: UInt64
    )
    /**
     * Publish or Upgrade is missing dependency
     */
    case publishUpgradeMissingDependency
    /**
     * Publish or Upgrade dependency downgrade.
     *
     * Indirect (transitive) dependency of published or upgraded package has
     * been assigned an on-chain version that is less than the version
     * required by one of the package's transitive dependencies.
     */
    case publishUpgradeDependencyDowngrade
    /**
     * Invalid package upgrade
     */
    case packageUpgrade(kind: PackageUpgradeError
    )
    /**
     * Indicates the transaction tried to write objects too large to storage
     */
    case writtenObjectsTooLarge(objectSize: UInt64, maxObjectSize: UInt64
    )
    /**
     * Certificate is on the deny list
     */
    case certificateDenied
    /**
     * IOTA Move Bytecode verification timed out.
     */
    case iotaMoveVerificationTimeout
    /**
     * The requested shared object operation is not allowed
     */
    case sharedObjectOperationNotAllowed
    /**
     * Requested shared object has been deleted
     */
    case inputObjectDeleted
    /**
     * Certificate is cancelled due to congestion on shared objects
     */
    case executionCancelledDueToSharedObjectCongestion(congestedObjects: [ObjectId]
    )
    /**
     * Certificate is cancelled due to congestion on shared objects;
     * suggested gas price can be used to give this certificate more priority.
     */
    case executionCancelledDueToSharedObjectCongestionV2(congestedObjects: [ObjectId], suggestedGasPrice: UInt64
    )
    /**
     * Address is denied for this coin type
     */
    case addressDeniedForCoin(address: Address, coinType: String
    )
    /**
     * Coin type is globally paused for use
     */
    case coinTypeGlobalPause(coinType: String
    )
    /**
     * Certificate is cancelled because randomness could not be generated this
     * epoch
     */
    case executionCancelledDueToRandomnessUnavailable
    /**
     * A valid linkage was unable to be determined for the transaction or one
     * of its commands.
     */
    case invalidLinkage
}


#if compiler(>=6)
extension ExecutionError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeExecutionError: FfiConverterRustBuffer {
    typealias SwiftType = ExecutionError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ExecutionError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .insufficientGas
        
        case 2: return .invalidGasObject
        
        case 3: return .invariantViolation
        
        case 4: return .featureNotYetSupported
        
        case 5: return .objectTooBig(objectSize: try FfiConverterUInt64.read(from: &buf), maxObjectSize: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 6: return .packageTooBig(objectSize: try FfiConverterUInt64.read(from: &buf), maxObjectSize: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 7: return .circularObjectOwnership(object: try FfiConverterTypeObjectId.read(from: &buf)
        )
        
        case 8: return .insufficientCoinBalance
        
        case 9: return .coinBalanceOverflow
        
        case 10: return .publishErrorNonZeroAddress
        
        case 11: return .iotaMoveVerification
        
        case 12: return .movePrimitiveRuntime(location: try FfiConverterOptionTypeMoveLocation.read(from: &buf)
        )
        
        case 13: return .moveAbort(location: try FfiConverterTypeMoveLocation.read(from: &buf), code: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 14: return .vmVerificationOrDeserialization
        
        case 15: return .vmInvariantViolation
        
        case 16: return .functionNotFound
        
        case 17: return .arityMismatch
        
        case 18: return .typeArityMismatch
        
        case 19: return .nonEntryFunctionInvoked
        
        case 20: return .commandArgument(argument: try FfiConverterUInt16.read(from: &buf), kind: try FfiConverterTypeCommandArgumentError.read(from: &buf)
        )
        
        case 21: return .typeArgument(typeArgument: try FfiConverterUInt16.read(from: &buf), kind: try FfiConverterTypeTypeArgumentError.read(from: &buf)
        )
        
        case 22: return .unusedValueWithoutDrop(result: try FfiConverterUInt16.read(from: &buf), subresult: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 23: return .invalidPublicFunctionReturnType(index: try FfiConverterUInt16.read(from: &buf)
        )
        
        case 24: return .invalidTransferObject
        
        case 25: return .effectsTooLarge(currentSize: try FfiConverterUInt64.read(from: &buf), maxSize: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 26: return .publishUpgradeMissingDependency
        
        case 27: return .publishUpgradeDependencyDowngrade
        
        case 28: return .packageUpgrade(kind: try FfiConverterTypePackageUpgradeError.read(from: &buf)
        )
        
        case 29: return .writtenObjectsTooLarge(objectSize: try FfiConverterUInt64.read(from: &buf), maxObjectSize: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 30: return .certificateDenied
        
        case 31: return .iotaMoveVerificationTimeout
        
        case 32: return .sharedObjectOperationNotAllowed
        
        case 33: return .inputObjectDeleted
        
        case 34: return .executionCancelledDueToSharedObjectCongestion(congestedObjects: try FfiConverterSequenceTypeObjectId.read(from: &buf)
        )
        
        case 35: return .executionCancelledDueToSharedObjectCongestionV2(congestedObjects: try FfiConverterSequenceTypeObjectId.read(from: &buf), suggestedGasPrice: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 36: return .addressDeniedForCoin(address: try FfiConverterTypeAddress.read(from: &buf), coinType: try FfiConverterString.read(from: &buf)
        )
        
        case 37: return .coinTypeGlobalPause(coinType: try FfiConverterString.read(from: &buf)
        )
        
        case 38: return .executionCancelledDueToRandomnessUnavailable
        
        case 39: return .invalidLinkage
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ExecutionError, into buf: inout [UInt8]) {
        switch value {
        
        
        case .insufficientGas:
            writeInt(&buf, Int32(1))
        
        
        case .invalidGasObject:
            writeInt(&buf, Int32(2))
        
        
        case .invariantViolation:
            writeInt(&buf, Int32(3))
        
        
        case .featureNotYetSupported:
            writeInt(&buf, Int32(4))
        
        
        case let .objectTooBig(objectSize,maxObjectSize):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(objectSize, into: &buf)
            FfiConverterUInt64.write(maxObjectSize, into: &buf)
            
        
        case let .packageTooBig(objectSize,maxObjectSize):
            writeInt(&buf, Int32(6))
            FfiConverterUInt64.write(objectSize, into: &buf)
            FfiConverterUInt64.write(maxObjectSize, into: &buf)
            
        
        case let .circularObjectOwnership(object):
            writeInt(&buf, Int32(7))
            FfiConverterTypeObjectId.write(object, into: &buf)
            
        
        case .insufficientCoinBalance:
            writeInt(&buf, Int32(8))
        
        
        case .coinBalanceOverflow:
            writeInt(&buf, Int32(9))
        
        
        case .publishErrorNonZeroAddress:
            writeInt(&buf, Int32(10))
        
        
        case .iotaMoveVerification:
            writeInt(&buf, Int32(11))
        
        
        case let .movePrimitiveRuntime(location):
            writeInt(&buf, Int32(12))
            FfiConverterOptionTypeMoveLocation.write(location, into: &buf)
            
        
        case let .moveAbort(location,code):
            writeInt(&buf, Int32(13))
            FfiConverterTypeMoveLocation.write(location, into: &buf)
            FfiConverterUInt64.write(code, into: &buf)
            
        
        case .vmVerificationOrDeserialization:
            writeInt(&buf, Int32(14))
        
        
        case .vmInvariantViolation:
            writeInt(&buf, Int32(15))
        
        
        case .functionNotFound:
            writeInt(&buf, Int32(16))
        
        
        case .arityMismatch:
            writeInt(&buf, Int32(17))
        
        
        case .typeArityMismatch:
            writeInt(&buf, Int32(18))
        
        
        case .nonEntryFunctionInvoked:
            writeInt(&buf, Int32(19))
        
        
        case let .commandArgument(argument,kind):
            writeInt(&buf, Int32(20))
            FfiConverterUInt16.write(argument, into: &buf)
            FfiConverterTypeCommandArgumentError.write(kind, into: &buf)
            
        
        case let .typeArgument(typeArgument,kind):
            writeInt(&buf, Int32(21))
            FfiConverterUInt16.write(typeArgument, into: &buf)
            FfiConverterTypeTypeArgumentError.write(kind, into: &buf)
            
        
        case let .unusedValueWithoutDrop(result,subresult):
            writeInt(&buf, Int32(22))
            FfiConverterUInt16.write(result, into: &buf)
            FfiConverterUInt16.write(subresult, into: &buf)
            
        
        case let .invalidPublicFunctionReturnType(index):
            writeInt(&buf, Int32(23))
            FfiConverterUInt16.write(index, into: &buf)
            
        
        case .invalidTransferObject:
            writeInt(&buf, Int32(24))
        
        
        case let .effectsTooLarge(currentSize,maxSize):
            writeInt(&buf, Int32(25))
            FfiConverterUInt64.write(currentSize, into: &buf)
            FfiConverterUInt64.write(maxSize, into: &buf)
            
        
        case .publishUpgradeMissingDependency:
            writeInt(&buf, Int32(26))
        
        
        case .publishUpgradeDependencyDowngrade:
            writeInt(&buf, Int32(27))
        
        
        case let .packageUpgrade(kind):
            writeInt(&buf, Int32(28))
            FfiConverterTypePackageUpgradeError.write(kind, into: &buf)
            
        
        case let .writtenObjectsTooLarge(objectSize,maxObjectSize):
            writeInt(&buf, Int32(29))
            FfiConverterUInt64.write(objectSize, into: &buf)
            FfiConverterUInt64.write(maxObjectSize, into: &buf)
            
        
        case .certificateDenied:
            writeInt(&buf, Int32(30))
        
        
        case .iotaMoveVerificationTimeout:
            writeInt(&buf, Int32(31))
        
        
        case .sharedObjectOperationNotAllowed:
            writeInt(&buf, Int32(32))
        
        
        case .inputObjectDeleted:
            writeInt(&buf, Int32(33))
        
        
        case let .executionCancelledDueToSharedObjectCongestion(congestedObjects):
            writeInt(&buf, Int32(34))
            FfiConverterSequenceTypeObjectId.write(congestedObjects, into: &buf)
            
        
        case let .executionCancelledDueToSharedObjectCongestionV2(congestedObjects,suggestedGasPrice):
            writeInt(&buf, Int32(35))
            FfiConverterSequenceTypeObjectId.write(congestedObjects, into: &buf)
            FfiConverterUInt64.write(suggestedGasPrice, into: &buf)
            
        
        case let .addressDeniedForCoin(address,coinType):
            writeInt(&buf, Int32(36))
            FfiConverterTypeAddress.write(address, into: &buf)
            FfiConverterString.write(coinType, into: &buf)
            
        
        case let .coinTypeGlobalPause(coinType):
            writeInt(&buf, Int32(37))
            FfiConverterString.write(coinType, into: &buf)
            
        
        case .executionCancelledDueToRandomnessUnavailable:
            writeInt(&buf, Int32(38))
        
        
        case .invalidLinkage:
            writeInt(&buf, Int32(39))
        
        }
    }
}


