// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * The status of an executed Transaction
 *
 * # BCS
 *
 * The BCS serialized form for this type is defined by the following ABNF:
 *
 * ```text
 * execution-status = success / failure
 * success = %d00
 * failure = %d01 execution-error (option u64)
 * ```
 */

public enum ExecutionStatus {
    
    /**
     * The Transaction successfully executed.
     */
    case success
    /**
     * The Transaction didn't execute successfully.
     *
     * Failed transactions are still committed to the blockchain but any
     * intended effects are rolled back to prior to this transaction
     * executing with the caveat that gas objects are still smashed and gas
     * usage is still charged.
     */
    case failure(
        /**
         * The error encountered during execution.
         */error: ExecutionError, 
        /**
         * The command, if any, during which the error occurred.
         */command: UInt64?
    )
}


#if compiler(>=6)
extension ExecutionStatus: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeExecutionStatus: FfiConverterRustBuffer {
    typealias SwiftType = ExecutionStatus

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ExecutionStatus {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .success
        
        case 2: return .failure(error: try FfiConverterTypeExecutionError.read(from: &buf), command: try FfiConverterOptionUInt64.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ExecutionStatus, into buf: inout [UInt8]) {
        switch value {
        
        
        case .success:
            writeInt(&buf, Int32(1))
        
        
        case let .failure(error,command):
            writeInt(&buf, Int32(2))
            FfiConverterTypeExecutionError.write(error, into: &buf)
            FfiConverterOptionUInt64.write(command, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeExecutionStatus_lift(_ buf: RustBuffer) throws -> ExecutionStatus {
    return try FfiConverterTypeExecutionStatus.lift(buf)
}

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeExecutionStatus_lower(_ value: ExecutionStatus) -> RustBuffer {
    return FfiConverterTypeExecutionStatus.lower(value)
}






