        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .childObjectId
        
        case 2: return .regularObjectId
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: HashingIntentScope, into buf: inout [UInt8]) {
        switch value {
        
        
        case .childObjectId:
            writeInt(&buf, Int32(1))
        
        
        case .regularObjectId:
            writeInt(&buf, Int32(2))
        
        }
    }
}


