     */
    case incompatibleUpgrade
    /**
     * Digest in upgrade ticket and computed digest differ
     */
    case digestDoesNotMatch(digest: Digest
    )
    /**
     * Upgrade policy is not valid
     */
    case unknownUpgradePolicy(policy: UInt8
    )
    /**
     * PackageId does not matach PackageId in upgrade ticket
     */
    case packageIdDoesNotMatch(packageId: ObjectId, ticketId: ObjectId
    )
}


