#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypePackageUpgradeError: FfiConverterRustBuffer {
    typealias SwiftType = PackageUpgradeError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PackageUpgradeError {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .unableToFetchPackage(packageId: try FfiConverterTypeObjectId.read(from: &buf)
        )
        
        case 2: return .notAPackage(objectId: try FfiConverterTypeObjectId.read(from: &buf)
        )
        
        case 3: return .incompatibleUpgrade
        
        case 4: return .digestDoesNotMatch(digest: try FfiConverterTypeDigest.read(from: &buf)
        )
        
        case 5: return .unknownUpgradePolicy(policy: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 6: return .packageIdDoesNotMatch(packageId: try FfiConverterTypeObjectId.read(from: &buf), ticketId: try FfiConverterTypeObjectId.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: PackageUpgradeError, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .unableToFetchPackage(packageId):
            writeInt(&buf, Int32(1))
            FfiConverterTypeObjectId.write(packageId, into: &buf)
            
        
        case let .notAPackage(objectId):
            writeInt(&buf, Int32(2))
            FfiConverterTypeObjectId.write(objectId, into: &buf)
            
        
        case .incompatibleUpgrade:
            writeInt(&buf, Int32(3))
        
        
        case let .digestDoesNotMatch(digest):
            writeInt(&buf, Int32(4))
            FfiConverterTypeDigest.write(digest, into: &buf)
            
        
        case let .unknownUpgradePolicy(policy):
            writeInt(&buf, Int32(5))
            FfiConverterUInt8.write(policy, into: &buf)
            
        
        case let .packageIdDoesNotMatch(packageId,ticketId):
            writeInt(&buf, Int32(6))
            FfiConverterTypeObjectId.write(packageId, into: &buf)
            FfiConverterTypeObjectId.write(ticketId, into: &buf)
            
