        case 3: return .secp256r1
        
        case 4: return .multisig
        
        case 5: return .bls12381
        
        case 6: return .zkLoginAuthenticatorDeprecated
        
        case 7: return .passkeyAuthenticator
        
        case 8: return .moveAuthenticator
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: SignatureScheme, into buf: inout [UInt8]) {
        switch value {
        
        
        case .ed25519:
            writeInt(&buf, Int32(1))
        
        
        case .secp256k1:
            writeInt(&buf, Int32(2))
        
        
        case .secp256r1:
            writeInt(&buf, Int32(3))
        
        
        case .multisig:
            writeInt(&buf, Int32(4))
        
        
        case .bls12381:
            writeInt(&buf, Int32(5))
        
        
        case .zkLoginAuthenticatorDeprecated:
            writeInt(&buf, Int32(6))
        
        
        case .passkeyAuthenticator:
            writeInt(&buf, Int32(7))
        
        
        case .moveAuthenticator:
